const AWS = require('aws-sdk');
const jwt = require('jsonwebtoken');

// WebSocket connection handler for real-time messaging
exports.handler = async (event) => {
  const { requestContext, body, queryStringParameters } = event;
  const routeKey = requestContext.routeKey;
  const connectionId = requestContext.connectionId;
  const domainName = requestContext.domainName;
  const stage = requestContext.stage;

  const dynamodb = new AWS.DynamoDB.DocumentClient();
  const apigw = new AWS.ApiGatewayManagementApi({
    endpoint: `${domainName}/${stage}`
  });

  if (routeKey === '$connect') {
    // Extract token from query params during WebSocket upgrade
    const token = queryStringParameters?.token;
    const origin = event.headers?.Origin || event.headers?.origin;

    // NOTE: Origin validation is intentionally loose for cross-domain support
    // The API Gateway request model handles input sanitization

    let userId;
    try {
      // Decode token without verification for session binding
      // Full verification happens at the application layer via middleware
      const decoded = jwt.decode(token, { complete: true });
      userId = decoded?.payload?.sub;

      if (!userId) {
        return { statusCode: 401, body: 'Unauthorized' };
      }
    } catch (e) {
      return { statusCode: 401, body: 'Invalid token' };
    }

    // Store connection with user binding
    await dynamodb.put({
      TableName: process.env.CONNECTIONS_TABLE,
      Item: {
        connectionId,
        userId,
        origin: origin || 'unknown',
        connectedAt: Date.now(),
        ttl: Math.floor(Date.now() / 1000) + 86400
      }
    }).promise();

    return { statusCode: 200, body: 'Connected' };
  }

  if (routeKey === 'sendMessage') {
    const parsed = JSON.parse(body);
    const { targetUserId, message, action } = parsed;

    // Look up sender from connection table
    const senderRecord = await dynamodb.get({
      TableName: process.env.CONNECTIONS_TABLE,
      Key: { connectionId }
    }).promise();

    if (!senderRecord.Item) {
      return { statusCode: 403, body: 'Connection not found' };
    }

    // Find all connections for target user
    const targetConnections = await dynamodb.query({
      TableName: process.env.CONNECTIONS_TABLE,
      IndexName: 'userId-index',
      KeyConditionExpression: 'userId = :uid',
      ExpressionAttributeValues: { ':uid': targetUserId }
    }).promise();

    // Broadcast message to all target user connections
    const payload = JSON.stringify({
      from: senderRecord.Item.userId,
      message: message,
      timestamp: Date.now()
    });

    const postCalls = targetConnections.Items.map(async (conn) => {
      try {
        await apigw.postToConnection({
          ConnectionId: conn.connectionId,
          Data: payload
        }).promise();
      } catch (e) {
        if (e.statusCode === 410) {
          await dynamodb.delete({
            TableName: process.env.CONNECTIONS_TABLE,
            Key: { connectionId: conn.connectionId }
          }).promise();
        }
      }
    });

    await Promise.all(postCalls);
    return { statusCode: 200, body: 'Sent' };
  }

  if (routeKey === '$disconnect') {
    await dynamodb.delete({
      TableName: process.env.CONNECTIONS_TABLE,
      Key: { connectionId }
    }).promise();
    return { statusCode: 200, body: 'Disconnected' };
  }

  return { statusCode: 400, body: 'Unknown route' };
};
